import type { ReactNode } from "react";
import { Icon } from "../../icons";

export interface SidebarProps {
  brandName?: string;
  brandMark?: ReactNode;
  /** Defaults to Booking’s decorative caret. Pass `null` to hide. Not an app switcher. */
  brandAction?: ReactNode | null;
  notes?: ReactNode;
  listMode?: boolean;
  children?: ReactNode;
  footer?: ReactNode;
  collapsed?: boolean;
  onToggleCollapsed?: () => void;
}

const defaultMark = (
  <svg width="17" height="17" viewBox="0 0 32 32" fill="none" aria-hidden="true">
    <path
      d="M4 8.5C4 6.6 5.6 5 7.5 5h13.8c4.2 0 7.6 3.4 7.6 7.6 0 4.2-3.4 7.6-7.6 7.6h-6.1l-8 6.4c-1.4 1.1-3.2.1-3.2-1.6V8.5Z"
      fill="var(--on-brand)"
    />
    <path d="M11 12.4h9.4" stroke="var(--accent)" strokeWidth="2.4" strokeLinecap="round" />
  </svg>
);

const defaultCaret = <Icon name="chevronDown" size={15} />;

export function Sidebar({
  brandName = "paryatech",
  brandMark,
  brandAction,
  notes,
  listMode = false,
  children,
  footer,
  collapsed = false,
  onToggleCollapsed,
}: SidebarProps) {
  const caret = brandAction === undefined ? defaultCaret : brandAction;

  return (
    <aside className="pt-side" aria-label="Sidebar">
      <div className="pt-side__top">
        <span className="pt-brand-mark">{brandMark ?? defaultMark}</span>
        <span className="pt-brand-name">{brandName}</span>
        {caret ? <span className="pt-brand-action">{caret}</span> : null}
      </div>

      {!listMode && notes ? <div className="pt-side__notes">{notes}</div> : null}

      <div className="pt-side__scroll">{children}</div>

      <div className="pt-side__foot">
        {footer}
        <button
          type="button"
          className="pt-side-collapse"
          data-tip={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          aria-expanded={!collapsed}
          aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          onClick={() => onToggleCollapsed?.()}
        >
          <Icon name="collapse" size={16} />
          <span className="pt-side-collapse__txt">Collapse</span>
        </button>
      </div>
    </aside>
  );
}

export function SidebarFooter({
  children,
  className = "",
}: {
  children: ReactNode;
  className?: string;
}) {
  return <div className={`pt-sidebar-footer ${className}`.trim()}>{children}</div>;
}

export default Sidebar;

import type { AnchorHTMLAttributes, ButtonHTMLAttributes, ReactNode } from "react";
import "./SidebarNav.css";

export interface NavItemData {
  id: string;
  label: string;
  icon: ReactNode;
  href?: string;
  active?: boolean;
  tip?: string;
  badge?: ReactNode;
  onSelect?: () => void;
}

export interface NavGroupData {
  id: string;
  label: string;
  items: NavItemData[];
}

export interface NavItemProps {
  id?: string;
  label: string;
  icon: ReactNode;
  href?: string;
  active?: boolean;
  tip?: string;
  badge?: ReactNode;
  onSelect?: () => void;
  className?: string;
}

type ButtonRest = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "onClick" | "children" | "className">;
type AnchorRest = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href" | "children" | "className">;

export function NavItem({
  label,
  icon,
  href,
  active = false,
  tip,
  badge,
  onSelect,
  className = "",
  ...rest
}: NavItemProps & ButtonRest & AnchorRest) {
  const cls = `pt-nav-item ${active ? "pt-nav-item--active" : ""} ${className}`.trim();
  const tipAttr = tip ?? label;
  const content = (
    <>
      <span className="pt-nav-item__icon" aria-hidden="true">
        {icon}
      </span>
      <span className="pt-nav-item__label">{label}</span>
      {badge != null && badge !== false ? <span className="pt-nav-item__badge">{badge}</span> : null}
    </>
  );

  if (href) {
    return (
      <a
        href={href}
        className={cls}
        data-tip={tipAttr}
        aria-current={active ? "page" : undefined}
        onClick={onSelect}
        {...(rest as AnchorRest)}
      >
        {content}
      </a>
    );
  }

  return (
    <button
      type="button"
      className={cls}
      data-tip={tipAttr}
      aria-current={active ? "page" : undefined}
      onClick={onSelect}
      {...(rest as ButtonRest)}
    >
      {content}
    </button>
  );
}

export interface NavGroupProps {
  label: string;
  children: ReactNode;
  className?: string;
}

export function NavGroup({ label, children, className = "" }: NavGroupProps) {
  return (
    <div className={`pt-nav-group ${className}`.trim()}>
      <div className="pt-nav-group__label">{label}</div>
      {children}
    </div>
  );
}

export interface SidebarNavProps {
  groups: NavGroupData[];
  className?: string;
  "aria-label"?: string;
}

export function SidebarNav({
  groups,
  className = "",
  "aria-label": ariaLabel = "Primary",
}: SidebarNavProps) {
  return (
    <nav className={`pt-sidenav ${className}`.trim()} aria-label={ariaLabel}>
      {groups.map((group) => (
        <NavGroup key={group.id} label={group.label}>
          {group.items.map((item) => (
            <NavItem
              key={item.id}
              label={item.label}
              icon={item.icon}
              href={item.href}
              active={item.active}
              tip={item.tip}
              badge={item.badge}
              onSelect={item.onSelect}
            />
          ))}
        </NavGroup>
      ))}
    </nav>
  );
}

export default SidebarNav;

.pt-sidenav {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.pt-nav-group {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.pt-nav-group__label {
  font-family: var(--type-label-group-family);
  font-size: var(--type-label-group-size);
  letter-spacing: var(--type-label-group-tracking);
  text-transform: var(--type-label-group-transform);
  color: var(--ink-2);
  font-weight: var(--type-label-group-weight);
  padding: 0 10px;
  margin: 16px 0 6px;
}

.pt-nav-group:first-child .pt-nav-group__label {
  margin-top: 0;
}

.pt-nav-item {
  display: flex;
  align-items: center;
  gap: 11px;
  height: 35px;
  padding: 0 11px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--ink-2);
  font-family: var(--type-label-nav-family);
  font-size: var(--type-label-nav-size);
  font-weight: var(--type-label-nav-weight);
  cursor: pointer;
  text-decoration: none;
  text-align: left;
  width: 100%;
  box-sizing: border-box;
  position: relative;
  min-width: 0;
}

.pt-nav-item svg,
.pt-nav-item__icon {
  flex: none;
  color: var(--ink-2);
  width: 17px;
  height: 17px;
  display: grid;
  place-items: center;
}

.pt-nav-item:hover {
  background: var(--side-hover);
  color: var(--ink);
}

.pt-nav-item:hover svg,
.pt-nav-item:hover .pt-nav-item__icon {
  color: var(--ink);
}

.pt-nav-item--active,
.pt-nav-item[aria-current="page"] {
  background: var(--pink-soft);
  color: var(--pink-ink);
  font-weight: var(--type-label-nav-weight-active);
}

.pt-nav-item--active svg,
.pt-nav-item--active .pt-nav-item__icon,
.pt-nav-item[aria-current="page"] svg,
.pt-nav-item[aria-current="page"] .pt-nav-item__icon {
  color: var(--pink);
}

.pt-nav-item__label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
}

.pt-nav-item__badge {
  margin-left: auto;
  flex: none;
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 6px;
  background: var(--surface-2);
  color: var(--ink-2);
  border: 1px solid var(--line);
  font-family: var(--type-mono-count-family);
  font-size: var(--type-mono-count-size);
  font-weight: var(--type-mono-count-weight);
}

/* Collapsed tips: right-anchored, only when shell is collapsed */
.pt-nav-item[data-tip]::after {
  content: attr(data-tip);
  position: absolute;
  left: calc(100% + 12px);
  top: 50%;
  transform: translateY(-50%);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  background: var(--tooltip-ink);
  color: var(--on-brand, #fff);
  font-family: var(--type-label-tooltip-family);
  font-size: var(--type-label-tooltip-size);
  font-weight: var(--type-label-tooltip-weight);
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  display: none;
  z-index: 400;
  box-shadow: var(--tooltipShadow);
}

.pt-frame--collapsed .pt-nav-item[data-tip]:hover::after,
.pt-frame--collapsed .pt-nav-item[data-tip]:focus-visible::after {
  display: block;
  opacity: 1;
}

.pt-frame--collapsed .pt-nav-group__label {
  display: none;
}

.pt-frame--collapsed .pt-nav-item {
  justify-content: center;
  padding: 0;
}

.pt-frame--collapsed .pt-nav-item__label,
.pt-frame--collapsed .pt-nav-item__badge {
  display: none;
}

.pt-frame {
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr);
  gap: 10px;
  height: 100vh;
  width: 100%;
  max-width: 100%;
  padding: 10px;
  background: var(--ground);
  transition: grid-template-columns var(--duration-shell) cubic-bezier(0.4, 0, 0.2, 1);
}

.pt-frame--collapsed {
  grid-template-columns: 66px minmax(0, 1fr);
}

.pt-side {
  display: flex;
  flex-direction: column;
  min-height: 0;
  background: var(--side);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  box-shadow: var(--panelShadow);
  overflow: hidden;
}

.pt-side__top {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 16px 16px 12px;
}

.pt-brand-mark {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  background: var(--accent);
  display: grid;
  place-items: center;
  flex: none;
}

.pt-brand-name {
  font-family: var(--type-heading-brand-family);
  font-weight: var(--type-heading-brand-weight);
  font-size: var(--type-heading-brand-size);
  letter-spacing: var(--type-heading-brand-tracking);
  color: var(--ink);
}

.pt-brand-action {
  margin-left: auto;
  color: var(--ink-2);
  display: inline-flex;
  align-items: center;
  flex: none;
}

.pt-frame--collapsed .pt-brand-name,
.pt-frame--collapsed .pt-brand-action,
.pt-frame--collapsed .pt-side-collapse__txt {
  display: none;
}

.pt-frame--collapsed .pt-side__top {
  justify-content: center;
  padding: 16px 0 12px;
}

.pt-frame--collapsed .pt-side__scroll {
  padding: 6px 8px 12px;
}

.pt-frame--collapsed .pt-side__foot {
  padding: 8px;
}

.pt-side__notes {
  margin: 0;
}

.pt-frame--list .pt-side__notes {
  display: none;
}

.pt-side__scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 6px 10px 12px;
}

.pt-side__foot {
  padding: 12px;
  border-top: 1px solid var(--line);
}

.pt-side-collapse {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 34px;
  padding: 0 11px;
  margin-top: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--ink-2);
  font-family: var(--type-label-compact-family);
  font-size: var(--type-label-compact-size);
  font-weight: var(--type-label-compact-weight);
  cursor: pointer;
  position: relative;
}

.pt-side-collapse:hover {
  background: var(--side-hover);
  color: var(--ink);
}

.pt-side-collapse svg {
  flex: none;
  transition: transform var(--duration-shell) cubic-bezier(0.4, 0, 0.2, 1);
}

.pt-frame--collapsed .pt-side-collapse {
  justify-content: center;
  padding: 0;
  margin-top: 12px;
}

.pt-frame--collapsed .pt-side-collapse svg {
  transform: rotate(180deg);
}

.pt-side-collapse[data-tip]::after {
  content: attr(data-tip);
  position: absolute;
  left: calc(100% + 12px);
  top: 50%;
  transform: translateY(-50%);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  background: var(--tooltip-ink);
  color: var(--on-brand, #fff);
  font-family: var(--type-label-tooltip-family);
  font-size: var(--type-label-tooltip-size);
  font-weight: var(--type-label-tooltip-weight);
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  display: none;
  z-index: 400;
  box-shadow: var(--tooltipShadow);
}

.pt-frame--collapsed .pt-side-collapse[data-tip]:hover::after {
  display: block;
  opacity: 1;
}

.pt-workspace {
  border-radius: var(--radius-lg);
  background: var(--panel-ground);
  border: 1px solid var(--line);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  box-shadow: var(--panelShadow);
  container-type: inline-size;
  container-name: shell;
}

.pt-topbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
  flex: none;
  min-width: 0;
}

.pt-topbar .pt-search,
.pt-topbar .pt-search--full {
  flex: 0 1 340px;
  max-width: 380px;
}

.pt-topbar__actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
  flex: none;
}

.pt-scroll {
  flex: 1;
  min-height: 0;
  min-width: 0;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--panel-ground);
  display: flex;
  flex-direction: column;
}

.pt-content {
  --page-pad: clamp(16px, 2.2cqi, 52px);
  width: 100%;
  max-width: 2000px;
  min-width: 0;
  margin: 0 auto;
  flex: 1 0 auto;
  display: flex;
  flex-direction: column;
  min-height: 100%;
  padding: 16px var(--page-pad) 0;
}

@media (min-width: 1440px) {
  .pt-frame {
    padding: 12px;
    gap: 12px;
  }
}

@media (min-width: 1920px) {
  .pt-frame {
    padding: 14px;
    gap: 14px;
  }
}

/* Matches --bp-shell (1000px); media queries cannot use custom props reliably */
@media (max-width: 1000px) {
  .pt-frame {
    grid-template-columns: 1fr;
    height: auto;
    min-height: 100vh;
    padding: 0;
    gap: 0;
    overflow: hidden;
  }
  .pt-side {
    display: none;
  }
  .pt-workspace {
    border-radius: 0;
    border: none;
    box-shadow: none;
    height: 100vh;
  }
}

@media (max-width: 900px) {
  .pt-topbar {
    padding: 8px 10px;
    gap: 6px;
    flex-wrap: wrap;
  }
  .pt-topbar .pt-search,
  .pt-topbar .pt-search--full {
    max-width: none;
    flex: 1 1 180px;
  }
}

@container shell (max-width: 900px) {
  .pt-topbar {
    padding: 8px 10px;
    gap: 6px;
    flex-wrap: wrap;
  }
  .pt-topbar .pt-search,
  .pt-topbar .pt-search--full {
    max-width: none;
    flex: 1 1 180px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .pt-frame {
    transition: none;
  }
  .pt-side-collapse svg {
    transition: none;
  }
}
